from decimal import Decimal, ROUND_HALF_UP

def run(payload):
    subtotal = Decimal(str(payload["subtotal"]))
    amount = subtotal - Decimal(str(payload["fixed"])) if "fixed" in payload else subtotal * (Decimal("1") - Decimal(str(payload.get("rate", 0))))
    return {"total": float(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}
